import { useState, type FormEvent } from 'react';
import { JxStepper, JxInputField, JxButton } from '@jinx-ui/react';

type StepIndex = 0 | 1 | 2;

interface RegistrationData {
  fullName: string;
  email: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState<StepIndex>(0);
  const [data, setData] = useState<RegistrationData>({
    fullName: '',
    email: '',
    street: '',
    city: '',
    postalCode: '',
  });

  const update = (field: keyof RegistrationData) => (e: React.ChangeEvent<HTMLInputElement>) => {
    setData((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const isLastStep = step === STEPS.length - 1;

  const handleNext = () => {
    if (!isLastStep) {
      setStep((prev) => (prev + 1) as StepIndex);
    }
  };

  const handleBack = () => {
    setStep((prev) => Math.max(prev - 1, 0) as StepIndex);
  };

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (isLastStep) {
      onSubmit(data);
    } else {
      handleNext();
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6, 24px)',
        maxWidth: '480px',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}>
          <JxInputField
            label="Полное имя"
            required
            value={data.fullName}
            onChange={update('fullName')}
          />
          <JxInputField
            label="Email"
            required
            helperText="Используется для входа и уведомлений"
            value={data.email}
            onChange={update('email')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}>
          <JxInputField
            label="Улица и дом"
            required
            value={data.street}
            onChange={update('street')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={update('city')}
          />
          <JxInputField
            label="Почтовый индекс"
            required
            value={data.postalCode}
            onChange={update('postalCode')}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2, 8px)' }}>
          <p>
            <strong>Имя:</strong> {data.fullName || '—'}
          </p>
          <p>
            <strong>Email:</strong> {data.email || '—'}
          </p>
          <p>
            <strong>Адрес:</strong> {[data.street, data.city, data.postalCode].filter(Boolean).join(', ') || '—'}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3, 12px)' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={handleBack}>
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Дальше
          </JxButton>
        )}
      </div>
    </form>
  );
}

